class ExpressionEvaluator:
    def __init__(self, expression: str):
        self.expression = expression.replace(" ", "")
        self.position = 0

    def parse(self) -> float:
        result = self._parse_expression()
        if self.position < len(self.expression):
            raise ValueError("Unexpected characters at the end of the expression.")
        return result

    def _parse_expression(self) -> float:
        result = self._parse_term()
        while self.position < len(self.expression):
            if self.expression[self.position] == '+':
                self.position += 1
                result += self._parse_term()
            elif self.expression[self.position] == '-':
                self.position += 1
                result -= self._parse_term()
            else:
                break
        return result

    def _parse_term(self) -> float:
        result = self._parse_factor()
        while self.position < len(self.expression):
            if self.expression[self.position] == '*':
                self.position += 1
                result *= self._parse_factor()
            elif self.expression[self.position] == '/':
                self.position += 1
                denominator = self._parse_factor()
                if denominator == 0:
                    raise ZeroDivisionError("Division by zero is not allowed.")
                result /= denominator
            else:
                break
        return result

    def _parse_factor(self) -> float:
        if self.position < len(self.expression):
            if self.expression[self.position] == '(':
                self.position += 1
                result = self._parse_expression()
                if self.position < len(self.expression) and self.expression[self.position] == ')':
                    self.position += 1
                    return result
                else:
                    raise ValueError("Mismatched parentheses.")
            else:
                start = self.position
                while (self.position < len(self.expression) and
                       (self.expression[self.position].isdigit() or
                        self.expression[self.position] == '.')):
                    self.position += 1
                if start == self.position:
                    raise ValueError("Unexpected character found.")
                return float(self.expression[start:self.position])
        raise ValueError("Unexpected end of expression.")

